const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('expo/config-plugins');

// Keep rules for the release build's R8 pass (enabled in withAndroidAbi).
//
// R8 strips and renames aggressively, and every library here finds classes by
// reflection or through JNI, where a renamed class is only discovered as a crash
// at runtime rather than a build error. android/ is regenerated by prebuild, so
// these live in a plugin instead of a hand-edited proguard-rules.pro.
const RULES = `
# ---- Added by plugins/withProguardRules.js ----

# Flatten every renamed class into the root package. Play reports this as
# "Repackage Classes" and it both shrinks the dex and makes the obfuscation
# worth having -- without it R8 renames classes but leaves the package tree,
# which still describes the app's structure. Anything held by a keep rule below
# keeps its name and its package, so the reflective lookups are unaffected.
-repackageclasses ''

# React Native / JNI: native methods and the classes they bind to.
-keepclasseswithmembernames class * { native <methods>; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.bridge.** { *; }
-keep class com.facebook.react.uimanager.** { *; }
-keep,includedescriptorclasses class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod <methods>; }
-dontwarn com.facebook.react.**

# Hermes
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jsi.** { *; }

# Expo modules are resolved by name at runtime.
-keep class expo.modules.** { *; }
-keep class * implements expo.modules.core.interfaces.Package { *; }
-dontwarn expo.modules.**

# Reanimated / gesture handler / screens / svg
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }
-keep class com.swmansion.rnscreens.** { *; }
-keep class com.horcrux.svg.** { *; }

# OkHttp / Okio (networking + the socket.io client)
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn javax.annotation.**
-keepnames class okhttp3.internal.publicsuffix.PublicSuffixDatabase

# Coil 3 (expo-image). Its OkHttp network fetcher references a multiplatform
# type that is not on the Android classpath; without this R8 fails outright.
-dontwarn coil3.PlatformContext
-keep class coil3.** { *; }

# Keep annotations, signatures and line numbers so crash reports stay readable.
-keepattributes *Annotation*, Signature, InnerClasses, SourceFile, LineNumberTable
-renamesourcefileattribute SourceFile
`;

const MARKER = 'Added by plugins/withProguardRules.js';

module.exports = function withProguardRules(config) {
  return withDangerousMod(config, [
    'android',
    (cfg) => {
      const file = path.join(
        cfg.modRequest.platformProjectRoot,
        'app',
        'proguard-rules.pro'
      );
      const existing = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
      if (!existing.includes(MARKER)) {
        fs.writeFileSync(file, `${existing.trimEnd()}\n${RULES}`);
      }
      return cfg;
    },
  ]);
};
